  const inputs = [c1, c2, c3, c4, c5];
  for (let column = 0; column < inputs.length; column++) {
    const label = "NormalizationTest 17.0.0 Part1 line " + line + " c" + (column + 1);
    assert.sameValue(inputs[column].normalize("NFC"), column < 3 ? c2 : c4, label + " NFC");
    assert.sameValue(inputs[column].normalize("NFD"), column < 3 ? c3 : c5, label + " NFD");
    assert.sameValue(inputs[column].normalize("NFKC"), c4, label + " NFKC");
    assert.sameValue(inputs[column].normalize("NFKD"), c5, label + " NFKD");
  }
